inputs.manifest:
{
  "schema_version": "1.0.0",
  "id": "z-image/inpaint",
  "label": {
    "en": "Inpaint",
    "ru": "Inpaint"
  },
  "family": "z-image",
  "family_label": "Z-Image Turbo",
  "tier": 0,
  "mode": "inpaint",
  "order": 30,
  "controls": [
    {
      "param": "prompt",
      "kind": "prompt",
      "superprompt": true
    },
    {
      "param": "seed",
      "kind": "seed"
    },
    {
      "param": "replace",
      "kind": "toggle",
      "default": false,
      "label": {
        "en": "Replace (full redraw)",
        "ru": "Replace (полная перерисовка)"
      },
      "tooltip": {
        "en": "Regenerate the masked region from scratch instead of reworking what is there. The strength slider is ignored — replacement always runs at full strength, the only mode this sampler is built for.",
        "ru": "Перерисовать область с нуля, а не переработать то, что есть. Слайдер силы при этом не используется: замена всегда идёт на полную, это единственный режим, на который рассчитан сэмплер."
      }
    },
    {
      "param": "denoise",
      "kind": "slider",
      "min": 0.1,
      "max": 0.5,
      "step": 0.05,
      "label": {
        "en": "Repaint strength",
        "ru": "Сила перерисовки"
      },
      "default": 0.35,
      "tooltip": {
        "en": "How far the masked area is reworked while keeping what is there. 0.1-0.2 refines texture and detail, 0.3-0.5 reshapes it. To replace the content entirely, turn Replace on.",
        "ru": "Насколько перерабатывается область с сохранением того, что в ней есть. 0.1–0.2 — уточнение текстуры и деталей, 0.3–0.5 — заметное изменение формы. Для полной замены включите Replace."
      }
    },
    {
      "param": "megapixels",
      "kind": "slider",
      "min": 0.5,
      "max": 4.0,
      "step": 0.1,
      "default": 0.8,
      "label": {
        "en": "Processing resolution",
        "ru": "Разрешение обработки"
      },
      "tooltip": {
        "en": "Megapixels the masked crop is redrawn at. A small selection is upscaled toward this budget (more detail, slower); an oversized one is scaled down to it.",
        "ru": "В скольких мегапикселях перерисовывается вырезанный по маске фрагмент. Маленькое выделение увеличивается до этого бюджета (больше деталей, дольше), слишком большое — уменьшается."
      }
    },
    {
      "param": "context_pct",
      "kind": "slider",
      "min": 0.0,
      "max": 50.0,
      "step": 1.0,
      "default": 25.0,
      "label": {
        "en": "Context around the mask",
        "ru": "Контекст вокруг маски"
      },
      "tooltip": {
        "en": "How much of the surroundings goes into the crop, as a percent of the mask. More context helps the model match what is around; it also enlarges the crop, so less of the budget lands on the mask.",
        "ru": "Сколько окружения попадает в вырез, в процентах от маски. Больше контекста — модель лучше попадает в окружение, но вырез растёт, и на саму маску приходится меньше бюджета."
      }
    },
    {
      "param": "loras",
      "kind": "loras",
      "max": 8,
      "strength": [
        -2.0,
        2.0
      ]
    },
    {
      "param": "think_steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 12,
      "label": {
        "en": "Think steps (quality)",
        "ru": "Шаги размышления (качество)"
      },
      "default": 2,
      "tooltip": {
        "en": "How many times the sampler re-checks the repaint against its surroundings on every step. Each turn is another pass through the model, so this is the main quality-versus-time knob: 2 is enough for an ordinary repaint, 5+ for a hard one.",
        "ru": "Сколько раз на каждом шаге сэмплер сверяет перерисовку с окружением. Каждый заход — это ещё один проход через модель, поэтому здесь и решается «качество против времени»: 2 хватает обычной правке, 5 и больше — сложной."
      }
    },
    {
      "param": "steps",
      "kind": "number",
      "advanced": true,
      "min": 1,
      "max": 60,
      "label": {
        "en": "Steps",
        "ru": "Шаги"
      }
    },
    {
      "param": "cfg",
      "kind": "number",
      "advanced": true,
      "min": 0,
      "max": 15,
      "step": 0.1,
      "label": {
        "en": "CFG",
        "ru": "CFG"
      }
    }
  ],
  "refs": {
    "max": 0
  },
  "requires": [
    "source_image",
    "mask"
  ],
  "negative_prompt": false,
  "models": [
    {
      "title": "studio:model",
      "input": "unet_name",
      "folder": "diffusion_models",
      "match": "z.?image.*turbo|Artius_ZImage"
    },
    {
      "title": "studio:clip",
      "input": "clip_name",
      "folder": "text_encoders",
      "match": "qwen_3_4b"
    },
    {
      "title": "studio:vae",
      "input": "vae_name",
      "folder": "vae",
      "match": "^ae\\.safetensors$"
    }
  ],
  "dependencies": [
    {
      "pack": "LanPaint",
      "nodes": [
        "LanPaint_KSampler",
        "LanPaint_MaskBlend"
      ]
    }
  ]
}
